alter table public.location_route_events add column if not exists from_favorite boolean not null default false;
create index if not exists idx_location_favorites_location on public.location_favorites(location_id);
create index if not exists idx_location_route_events_location on public.location_route_events(location_id,created_at desc);
create or replace function public.location_favorite_route_metrics(p_location_id uuid) returns table(favorite_count bigint,routed_count bigint,favorite_routed_count bigint) language sql stable security definer set search_path=public as $$ select (select count(*) from public.location_favorites lf where lf.location_id=p_location_id),(select count(*) from public.location_route_events re where re.location_id=p_location_id),(select count(*) from public.location_route_events re where re.location_id=p_location_id and re.from_favorite=true); $$;
create or replace function public.record_location_route_event(p_location_id uuid,p_from_favorite boolean default false) returns void language plpgsql security invoker set search_path=public as $$ begin insert into public.location_route_events(user_id,location_id,from_favorite) values(auth.uid(),p_location_id,p_from_favorite); end; $$;
